/// <summary>
/// One probe of the detailed catalog (Domenia 1 Domenia-ProbeCatalog.json, schema 1, documentation reviewed on 13/10/2026):
/// read-only WMI/CIM class, properties kept, filter, cost, what an unknown value means and what the probe does not prove.
/// <see cref="Reading"/> is the interpreted reading that opens it. No method is ever invoked.
/// </summary>
public sealed record ProbeInfo(
    string Id,
    string Name,
    string Category,
    string Namespace,
    string Class,
    ImmutableArray<string> Properties,
    string Filter,
    bool Slow,
    string Description,
    string Limitations,
    string UnknownMeaning,
    string Reading);

